    [5029]={name="Talisman of the Naga Lord",quality=2,ilvl=47,reqLevel=42,sourceType="world_drop",instructions="Drops from Lord Sakrasis (rare spawn).",zone="Booty Bay",npc="Lord Sakrasis"},
    [5069]={name="Fire Wand",quality=2,ilvl=12,reqLevel=7,sourceType="world_drop",instructions="World drop around level 6-14."},
    [5071]={name="Shadow Wand",quality=2,ilvl=14,reqLevel=9,sourceType="world_drop",instructions="World drop around level 9-15."},
    [5092]={name="Charred Razormane Wand",quality=1,ilvl=23,reqLevel=18,sourceType="world_drop",instructions="Drops from Razormane Seer.",zone="Kalimdor",npc="Razormane Seer"},
    [5183]={name="Pulsating Hydra Heart",quality=3,ilvl=20,reqLevel=15,sourceType="world_drop",instructions="Drops from Gesharahan (rare spawn).",zone="Wailing Caverns",npc="Gesharahan"},
    [5198]={name="Cookie's Stirring Rod",quality=3,ilvl=22,reqLevel=17,sourceType="boss_drop",instructions="Drops from Cookie.",zone="The Deadmines",npc="Cookie"},
    [5201]={name="Emberstone Staff",quality=3,ilvl=23,reqLevel=18,sourceType="boss_drop",instructions="Drops from Captain Greenskin.",zone="The Deadmines",npc="Captain Greenskin"},
    [5202]={name="Corsair's Overshirt",quality=3,ilvl=24,reqLevel=19,sourceType="boss_drop",instructions="Drops from Edwin VanCleef.",zone="The Deadmines",npc="Edwin VanCleef"},
    [5207]={name="Opaque Wand",quality=2,ilvl=20,reqLevel=15,sourceType="world_drop",instructions="World drop around level 15-21."},
    [5208]={name="Smoldering Wand",quality=1,ilvl=20,reqLevel=15,sourceType="vendor",instructions="Bought from Ardwyn Cailen.",zone="Eastern Kingdoms",npc="Ardwyn Cailen"},
    [5209]={name="Gloom Wand",quality=1,ilvl=21,reqLevel=16,sourceType="vendor",instructions="Bought from Ardwyn Cailen.",zone="Eastern Kingdoms",npc="Ardwyn Cailen"},
    [5210]={name="Burning Wand",quality=1,ilvl=25,reqLevel=20,sourceType="vendor",instructions="Bought from Ardwyn Cailen.",zone="Eastern Kingdoms",npc="Ardwyn Cailen"},
    [5211]={name="Dusk Wand",quality=1,ilvl=25,reqLevel=20,sourceType="vendor",instructions="Bought from Ardwyn Cailen.",zone="Eastern Kingdoms",npc="Ardwyn Cailen"},
    [5212]={name="Blazing Wand",quality=2,ilvl=17,reqLevel=12,sourceType="world_drop",instructions="World drop around level 11-18."},
    [5213]={name="Scorching Wand",quality=2,ilvl=35,reqLevel=30,sourceType="world_drop",instructions="World drop around level 27-36."},
    [5214]={name="Wand of Eventide",quality=2,ilvl=32,reqLevel=27,sourceType="world_drop",instructions="World drop around level 26-33."},
    [5215]={name="Ember Wand",quality=2,ilvl=41,reqLevel=36,sourceType="world_drop",instructions="World drop around level 36-42."},
    [5216]={name="Umbral Wand",quality=2,ilvl=45,reqLevel=40,sourceType="world_drop",instructions="World drop around level 38-47."},
    [5236]={name="Combustible Wand",quality=1,ilvl=34,reqLevel=29,sourceType="vendor",instructions="Bought from Ardwyn Cailen.",zone="Eastern Kingdoms",npc="Ardwyn Cailen"},
    [5238]={name="Pitchwood Wand",quality=1,ilvl=45,reqLevel=40,sourceType="vendor",instructions="Bought from Ardwyn Cailen.",zone="Eastern Kingdoms",npc="Ardwyn Cailen"},
    [5239]={name="Blackbone Wand",quality=1,ilvl=46,reqLevel=41,sourceType="vendor",instructions="Bought from Ardwyn Cailen.",zone="Eastern Kingdoms",npc="Ardwyn Cailen"},
    [5240]={name="Torchlight Wand",quality=2,ilvl=21,sourceType="quest_reward",instructions="Reward from the quest 'The Coastal Menace'. Pick it over the other reward choices. Starts with Captain Grayson in Westfall. Objective: Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.",zone="Westfall",questName="The Coastal Menace",lore="When my life was ended upon the rocks, I had no clue what the afterlife held for me. The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off."},
    [5241]={name="Dwarven Flamestick",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Gathering Idols'. Pick it over the other reward choices. Starts with Magmar Fellhew in Loch Modan. Objective: Bring Magmar Fellhew 8 Carved Stone Idols.",zone="Loch Modan",questName="Gathering Idols",lore="Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!"},
    [5242]={name="Cinder Wand",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Arugal's Folly'. Pick it over the other reward choices. Starts with Dalar Dawnweaver in Silverpine Forest. Objective: Bring 6 Worgen Bits to Dalar Dawnweaver in The Sepulcher.",zone="Silverpine Forest",questName="Arugal's Folly",lore="As my understanding of Arugal's magic grows so does my disdain for the hapless fool. I am close to completing my research on his so called remedy."},
    [5244]={name="Consecrated Wand",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Worgen in the Woods'. Starts with Calor in Duskwood. Objective: Bring Calor's note to Jonathan Carevin.",zone="Duskwood",questName="Worgen in the Woods",lore="Here you go. Bring this message to Master Carevin. A few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today."},
    [5246]={name="Excavation Rod",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Ormer's Revenge'. Pick it over the other reward choices. Starts with Ormer Ironbraid in Wetlands. Objective: Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.",zone="Wetlands",questName="Ormer's Revenge",lore="While you were down there I happened to notice that one of those beasts stood out from the rest. He was bigger and more menacing. I bet he's the one who led the others here to cause the disruption to the dig site."},
    [5247]={name="Rod of Sorrow",quality=2,ilvl=39,sourceType="quest_reward",instructions="Reward from the quest 'Wanted! Otto and Falconcrest'. Pick it over the other reward choices.",zone="Arathi Highlands",questName="Wanted!  Otto and Falconcrest",lore="The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto. Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts."},
    [5249]={name="Burning Sliver",quality=2,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'Crushridge Warmongers'. Pick it over the other reward choices. Starts with Marshal Redpath in Alterac Mountains. Objective: Slay 15 Crushridge Warmongers, then return to Marshal Redpath in Southshore.",zone="Alterac Mountains",questName="Crushridge Warmongers",lore="Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses... Go into the Ruins of Alterac and seek out the Crushridge Warmongers."},
    [5250]={name="Charred Wand",quality=2,ilvl=28,sourceType="quest_reward",instructions="Reward from the quest 'Dangerous!'. Pick it over the other reward choices. The quest is in Hillsbrad Foothills. Objective: High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.",zone="Hillsbrad Foothills",questName="Dangerous!",lore="Dangerous! The following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia: Clerk Horrace Whitesteed."},
    [5252]={name="Wand of Decay",quality=2,ilvl=21,sourceType="quest_reward",instructions="Reward from the quest 'Beren's Peril'. Starts with Shadow Priest Allister in Silverpine Forest. Objective: Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.",zone="Silverpine Forest",questName="Beren's Peril",lore="I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud."},
    [5253]={name="Goblin Igniter",quality=2,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'Venture Company Mining'. Pick it over the other reward choices. Starts with Crank Fizzlebub in Stranglethorn Vale. Objective: Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay.",zone="Stranglethorn Vale",questName="Venture Company Mining",lore="The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold! Please, you must help me!"},
    [5274]={name="Rose Mantle",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Morganth'. Starts with Theocritus in Redridge Mountains. Objective: Defeat Morganth.Bring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest.",zone="Redridge Mountains",questName="Morganth",lore="After much observation, I have discovered Morganth's plans. He searches for the Scythe of Elune...and he may have found it! If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might."},
    [5306]={name="Wind Rider Staff",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Cry of the Thunderhawk'. Pick it over the other reward choices. Starts with Jorn Skyseer in The Barrens. Objective: Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo.",zone="The Barrens",questName="Cry of the Thunderhawk",lore="The thunderhawk, is a fierce beast. It is time for you to face them. You must find where it roams, and bring me its wings as proof of your successful hunt."},
    [5310]={name="Sea Dog Britches",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'The Guns of Northwatch'. Pick it over the other reward choices. Starts with Captain Thalo'thas Brightsun in The Barrens. Objective: Captain Thalo'thas Brightsun of Ratchet wants you to collect 10 Theramore Medals and slay Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe.",zone="The Barrens",questName="The Guns of Northwatch",lore="Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold! Those bastards must be dealt with. Their paranoia has them in a state of frenzy."},
    [5313]={name="Totemic Clan Ring",quality=2,ilvl=25,sourceType="quest_reward",instructions="Reward from the quest 'Revenge of Gann'. Starts with Gann Stonespire in The Barrens. Objective: Destroy the flying machine at Bael Modan and return to Gann Stonespire.",zone="The Barrens",questName="Revenge of Gann",lore="Following Khazgorm's plans it should be no problem to fashion an explosive charge Ah, there we go. Now, I am going to entrust you with a special task."},
    [5315]={name="Timberland Armguards",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'WANTED: Murkdeep!'. Pick it over the other reward choices.",zone="Darkshore",questName="WANTED: Murkdeep!",lore="Attention! A reward is being offered for the death of the murloc \"Murkdeep\"."},
    [5321]={name="Elegant Shortsword",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Serena Bloodfeather'. Pick it over the other reward choices. Starts with Darsok Swiftdagger in The Barrens. Objective: Slay Serena Bloodfeather and return her head to Darsok Swiftdagger at the Crossroads.",zone="The Barrens",questName="Serena Bloodfeather",lore="You did so well with the lieutenants and underlings that I'd like you to do one last thing for me. Serena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago."},
    [5323]={name="Everglow Lantern",quality=2,ilvl=25,sourceType="quest_reward",instructions="Reward from the quest 'Weapons of Choice'. Pick it over the other reward choices. Starts with Tatternack Steelforge in The Barrens. Objective: Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.",zone="The Barrens",questName="Weapons of Choice",lore="The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons.",proc="Use: Heal your target for 135 to 165. (30 Min Cooldown)"},
    [5326]={name="Flaring Baton",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'The Escape'. Pick it over the other reward choices. Starts with Wizzlecrank's Shredder in The Barrens. Objective: Protect Wizzlecrank and the stolen goblin shredder on the way to Sputtervalve in Ratchet.",zone="The Barrens",questName="The Escape",lore="I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?"},
    [5337]={name="Wayfaring Gloves",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Stolen Booty'. Pick it over the other reward choices. Starts with Gazlowe in The Barrens. Objective: Retrieve the Shipment of Boots and Telescopic Lens for Gazlowe in Ratchet.",zone="The Barrens",questName="Stolen Booty",lore="While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have! As you see, my observatory is ready to go, but it needs the smaller of the two lenses."},
    [5340]={name="Cauldron Stirrer",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Apothecary Zamah'. Starts with Apothecary Helbrim in Thunder Bluff. Objective: Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up.",zone="The Barrens",questName="Apothecary Zamah",lore="I have rendered the spores you gave me into an emulsion. I must now send it to my associate, Apothecary Zamah. If you were to carry this to her, she can offer you something from our stores of alchemical goods."},
    [5343]={name="Barkeeper's Cloak",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Raptor Horns'. Starts with Mebok Mizzyrix in The Barrens. Objective: Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet.",zone="The Barrens",questName="Raptor Horns",lore="The raptors of the Barrens are smarter than raptors in other lands. And I think all that smarts is hiding in their horns!"},
    [5347]={name="Pestilent Wand",quality=1,ilvl=35,reqLevel=30,sourceType="vendor",instructions="Bought from Ardwyn Cailen.",zone="Eastern Kingdoms",npc="Ardwyn Cailen"},
    [5351]={name="Bounty Hunter's Ring",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Hezrul Bloodmark'. Starts with Regthar Deathgate in The Barrens. Objective: Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads.",zone="The Barrens",questName="Hezrul Bloodmark",lore="Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."},
    [5356]={name="Branding Rod",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Isha Awak'. Pick it over the other reward choices. Starts with Mahren Skyseer in The Barrens. Objective: Bring the Heart of Isha Awak to Mahren Skyseer.",zone="The Barrens",questName="Isha Awak",lore="The grand Isha Awak is lord of these waters. Great is his strength, and solemn his pride. The humans on the coast fear him, for he has consumed many of their number."},
    [5420]={name="Banshee Armor",quality=2,ilvl=14,sourceType="quest_reward",instructions="Reward from the quest 'The Demon Seed'. Starts with Ak'Zeloth in The Barrens. Objective: Grab a Flawed Power Stone. Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth.",zone="Durotar",questName="The Demon Seed",lore="The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire. I have prepared power stones that when placed near the Seed will disrupt its connection to the Legion."},
    [5458]={name="Dirtwood Belt",quality=1,ilvl=10,sourceType="quest_reward",instructions="Reward from the quest 'Oakenscowl'. Pick it over the other reward choices. Starts with Denalan in Teldrassil. Objective: Denalan at Lake Al'Ameth wants you to collect the Gargantuan Tumor from Oakenscowl.",zone="Teldrassil",questName="Oakenscowl",lore="In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home."},
    [5540]={name="Pearl-handled Dagger",quality=2,ilvl=23,reqLevel=18,sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [5542]={name="Pearl-clasped Cloak",quality=2,ilvl=19,reqLevel=14,sourceType="profession",instructions="Crafted with Tailoring (requires skill 1).",profession="Tailoring"},
    [5590]={name="Cord Bracers",quality=1,ilvl=11,sourceType="quest_reward",instructions="Reward from the quest 'Mist'. Pick it over the other reward choices. The quest is in Teldrassil. Objective: Escort Mist to Sentinel Arynia Cloudsbreak at the moon well near the Oracle Tree.",zone="Teldrassil",questName="Mist",lore="The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach."},
    [5591]={name="Rain-spotted Cape",quality=1,ilvl=11,sourceType="quest_reward",instructions="Reward from the quest 'The Enchanted Glade'. Pick it over the other reward choices. Starts with Sentinel Arynia Cloudsbreak in Teldrassil. Objective: Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade.",zone="Teldrassil",questName="The Enchanted Glade",lore="I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."},
    [5604]={name="Elven Wand",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Bashal'Aran'. Pick it over the other reward choices. Starts with Asterion in Darkshore. Objective: Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran.",zone="Darkshore",questName="Bashal'Aran",lore="It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color."},
    [5606]={name="Gardening Gloves",quality=1,ilvl=9,sourceType="quest_reward",instructions="Reward from the quest 'Timberling Sprouts'. Pick it over the other reward choices. Starts with Denalan in Teldrassil. Objective: Bring 12 Timberling Sprouts to Denalan at Lake Al'Ameth.",zone="Teldrassil",questName="Timberling Sprouts",lore="Small timberlings are sprouting around the waters of Lake Al'Ameth. I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble."},
    [5610]={name="Gustweald Cloak",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Cave Mushrooms'. Starts with Barithras Moonshade in Darkshore. Objective: Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine.",zone="Darkshore",questName="Cave Mushrooms",lore="I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave. The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains."},
    [5611]={name="Tear of Grief",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'For Love Eternal'.",zone="Darkshore",questName="For Love Eternal",lore="In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya."},
    [5613]={name="Staff of the Purifier",quality=2,ilvl=23,sourceType="quest_reward",instructions="Reward from the quest 'The Tower of Althalaxx'. Pick it over the other reward choices. Starts with Balthule Shadowstrike in Ashenvale. Objective: Talk to Delgren the Purifier at Maestra's Post.",zone="Darkshore",questName="The Tower of Althalaxx",lore="Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine, a place of great evil in southwestern Ashenvale.",proc="Use: Purifies the friendly target, removing 1 disease effect and 1 poison effect. (5 Min Cooldown)"},
    [5622]={name="Clergy Ring",quality=2,ilvl=22,sourceType="quest_reward",instructions="Reward from the quest 'The Tower of Althalaxx'. Pick it over the other reward choices. Starts with Balthule Shadowstrike in Ashenvale. Objective: Talk to Delgren the Purifier at Maestra's Post.",zone="Darkshore",questName="The Tower of Althalaxx",lore="Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine, a place of great evil in southwestern Ashenvale."},
    [5627]={name="Relic Blade",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'The Absent Minded Prospector'. Pick it over the other reward choices.",zone="Darkshore",questName="The Absent Minded Prospector",lore="When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil. While I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost."},
    [5743]={name="Prismstone Ring",quality=2,ilvl=40,reqLevel=35,sourceType="world_drop",instructions="Drops from Geomancer Flintdagger (rare spawn).",zone="Hammerfall",npc="Geomancer Flintdagger"},
    [5766]={name="Lesser Wizard's Robe",quality=2,ilvl=27,reqLevel=22,sourceType="profession",instructions="Crafted with Tailoring (requires skill 1).",profession="Tailoring"},
    [5770]={name="Robes of Arcana",quality=2,ilvl=30,reqLevel=25,sourceType="profession",instructions="Crafted with Tailoring (requires skill 1).",profession="Tailoring"},
    [5812]={name="Robes of Antiquity",quality=2,ilvl=25,sourceType="quest_reward",instructions="Reward from the quest 'Ruuzel'. Starts with Talen in Ashenvale. Objective: Bring the Ring of Zoram to Talen near the Zoram Strand.",zone="Ashenvale",questName="Ruuzel",lore="I fear the ancient statuette's secrets will remain forever hidden unless you find the key to its ancient lock. That key is a ring, the Ring of Zoram."},
    [5818]={name="Moonbeam Wand",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Answered Questions'. Pick it over the other reward choices. Starts with Jonathan Carevin in Darnassus. Objective: Return to Thyn'tel Bladeweaver in Darnassus.",zone="Ashenvale",questName="Answered Questions",lore="We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions."},
    [5820]={name="Faerie Mantle",quality=2,ilvl=32,sourceType="quest_reward",instructions="Reward from the quest 'The Branch of Cenarius'. Pick it over the other reward choices. Starts with Anilia in Ashenvale. Objective: Kill Geltharis and return the Branch of Cenarius to Illiyana at the Shrine of Aessina.",zone="Ashenvale",questName="The Branch of Cenarius",lore="Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body."},
    [5965]={name="Guardian Cloak",quality=2,ilvl=37,reqLevel=32,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [5967]={name="Girdle of Nobility",quality=2,ilvl=18,reqLevel=13,sourceType="world_drop",instructions="Drops from Brainwashed Noble (rare spawn).",zone="The Deadmines",npc="Brainwashed Noble"},
    [6062]={name="Heavy Cord Bracers",quality=1,ilvl=10,sourceType="quest_reward",instructions="Reward from the quest 'Thwarting Kolkar Aggression'. Pick it over the other reward choices. Starts with Lar Prowltusk in Durotar. Objective: Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag.",zone="Durotar",questName="Thwarting Kolkar Aggression",lore="Lower your voice. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag."},
    [6095]={name="Wandering Boots",quality=2,ilvl=24,sourceType="quest_reward",instructions="Reward from the quest 'Return to Kristoff'. Starts with Brother Paxton in Stormwind City. Objective: Return to Brother Kristoff in the Cathedral Square. Give him the book The Stresses of Iron.",zone="Stormwind City",questName="Return to Kristoff",lore="Now that I've finished copying the book, here's the original Stresses of Iron. Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay."},
    [6191]={name="Kimbra Boots",quality=2,ilvl=23,sourceType="quest_reward",instructions="Reward from the quest 'WANTED: Chok'sul'. Pick it over the other reward choices.",zone="Loch Modan",questName="WANTED: Chok'sul",lore="By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."},
    [6215]={name="Balanced Fighting Stick",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: \"Hogger\"'. Pick it over the other reward choices.",zone="Elwynn Forest",questName="Wanted:  \"Hogger\"",lore="Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."},
    [6226]={name="Bloody Apron",quality=3,ilvl=23,reqLevel=18,sourceType="boss_drop",instructions="Drops from Razorclaw the Butcher.",zone="Shadowfang Keep",npc="Razorclaw the Butcher"},
