    [18545]={name="Leggings of Arcane Supremacy",quality=4,ilvl=69,reqLevel=60,sourceType="boss_drop",instructions="Drops from Azuregos.",zone="Kalimdor",npc="Azuregos",lore="A blue dragon set by Malygos to watch over arcane secrets in Azshara, and not remotely pleased about visitors."},
    [18586]={name="Lonetree's Circle",quality=3,ilvl=35,sourceType="quest_reward",instructions="Reward from the quest 'Service to the Horde'. Pick it over the other reward choices. Starts with Zor Lonetree in Orgrimmar. Objective: It will take time for our scholars to study the pendant you brought us. &nbsp;But for your service to the Horde I would like to offer you a small token.Thank you, &lt;name&gt;. &nbsp;Your acts bring honor to you, and to us.",zone="Dustwallow Marsh",questName="Service to the Horde"},
    [18678]={name="Tempestria's Frozen Necklace",quality=3,ilvl=61,reqLevel=56,sourceType="world_drop",instructions="Drops from Princess Tempestria (rare elite).",zone="Winterspring",npc="Princess Tempestria"},
