    [19337]={name="The Black Book",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Razorgore the Untamed.",zone="Blackwing Lair",npc="Razorgore the Untamed",lore="Set to guard the stolen dragon eggs. The raid takes control of the orb he is chained to and turns him on the clutch he was protecting.",proc="Use: Empowers your pet, increasing its spell damage by 200, its attack power by 325, and its armor by 1600 for 30 sec. This spell will only affect an Imp, Succubus, Voidwalker, Fel"},
    [19355]={name="Shadow Wing Focus Staff",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ebonroc.",zone="Blackwing Lair",npc="Ebonroc",lore="One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."},
    [19366]={name="Master Dragonslayer's Orb",quality=4,ilvl=83,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Lord of Blackrock'. Pick it over the other reward choices. Starts with Highlord Bolvar Fordragon in Stormwind City. Objective: Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi.",zone="Stormwind City",questName="The Lord of Blackrock"},
    [19379]={name="Neltharion's Tear",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
    [19384]={name="Master Dragonslayer's Ring",quality=4,ilvl=83,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Lord of Blackrock'. Pick it over the other reward choices. Starts with Highlord Bolvar Fordragon in Stormwind City. Objective: Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi.",zone="Stormwind City",questName="The Lord of Blackrock"},
    [19403]={name="Band of Forced Concentration",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ebonroc.",zone="Blackwing Lair",npc="Ebonroc",lore="One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."},
    [19406]={name="Drake Fang Talisman",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ebonroc.",zone="Blackwing Lair",npc="Ebonroc",lore="Cut from the fang of one of Nefarian's drakes. Tanks wore it for the stun it shrugs off, not the numbers on it."},
    [19426]={name="Orb of the Darkmoon",quality=4,ilvl=65,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest '1200 Tickets - Orb of the Darkmoon'. Starts with Gelvas Grimegate in Mulgore. Objective: ProgressStep right up, step right up! &nbsp;If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so! &nbsp;You can redeem tickets in various denominations for wondrous and fantastic prizes. &nbsp;Don't be shy, give it a try!",zone="Mulgore",questName="1200 Tickets - Orb of the Darkmoon"},
    [19431]={name="Styleen's Impeding Scarab",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Flamegor.",zone="Blackwing Lair",npc="Flamegor",lore="The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on."},
