    [20033]={name="Zandalar Demoniac's Robe",quality=4,ilvl=65,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Demoniac's Robes'.",zone="Zul'Gurub",questName="Paragons of Power: The Demoniac's Robes",lore="The ultimate symbol of power amongst the tribe is the garb we wear in battle. A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric."},
