    [21118]={name="Talisman of Arathor",quality=3,ilvl=43,reqLevel=38,sourceType="vendor",instructions="Bought from Samuel Hawke.",zone="Refuge Pointe",npc="Samuel Hawke",proc="Use: Absorbs 310 to 378 physical damage.  Lasts 15 sec. (3 Min Cooldown)"},
